mapper.select:
select TIC.id, TIC.REL_ID, TIC.CHANGE_KEY, TIC.CHANGE_VALUE, TIC.IS_CHANGE, TIC.IS_DELETE, TIC.REMARK, TIC.CREATE_BY, TIC.UPDATE_BY, TIC.CREATE_TIME, TIC.UPDATE_TIME, TIR.MODE_NAME, TIR.FILE_NAME, TIR.IS_PAGE from T_I18N_CHANGE TIC left join T_I18N_RELATION TIR on TIC.REL_ID = TIR.ID where TIC.IS_DELETE = 0
and TIR.IS_PAGE = #{isPage}
and TIC.IS_CHANGE = #{isChange}
and TIC.id = #{id}
and TIC.CHANGE_KEY like concat(concat('%', #{changeKey}),'%')
and TIC.CHANGE_VALUE like concat(concat('%', #{changeValue}),'%')
and TIR.MODE_NAME like concat(concat('%', #{modeName}),'%')
and (1,TIR.FILE_NAME) in
(1,#{item})
order by ${params.orderBy}

mapper.update:
update T_I18N_CHANGE
set CHANGE_VALUE = #{changeValue},
    IS_CHANGE    = #{isChange},
    UPDATE_BY    = #{updateBy},
    UPDATE_TIME  = #{updateTime}
where id = #{id}
